D=Path(__file__).resolve().parents[1];W=D.parents[1]
def sha(p):
 h=hashlib.sha256()
 with open(p,'rb') as f:
  for b in iter(lambda:f.read(1024*1024),b''):h.update(b)
 return h.hexdigest()
def save(p,v):(D/p).write_text(json.dumps(v,indent=2,ensure_ascii=False)+'\n')
